INSERT INTO `assignments` VALUES (1,1,'Responsive RESTful Web Portal Architecture','Implement an end-to-end CRUD web application using PHP PDO, Bootstrap 5, and JavaScript Fetch API with session authentication.','2026-10-05',2,NULL,NULL),(2,2,'Complex Relational Schema Normalization & Triggers','Design an E-Commerce enterprise schema, perform 3NF normalization, and write triggers for automatic stock auditing.','2026-10-08',49,NULL,NULL),(3,3,'Packet Inspection & Subnetting Case Study','Perform Wireshark packet capture analysis on TCP 3-way handshake and design a VLSM subnet hierarchy for 500 hosts.','2026-10-12',50,NULL,NULL),(4,4,'Turing Machine & PDA State Transition Graphs','Construct a Pushdown Automaton for context-free grammar palindrome acceptance and formulate formal pumping lemma proofs.','2026-10-10',51,NULL,NULL),(5,5,'A* Search & Neural Classification Mini-Project','Implement the A* heuristic pathfinder on grid graph obstacles and train a multi-layer perceptron on student classification data.','2026-10-15',52,NULL,NULL),(6,6,'Dockerized Microservices CI/CD Pipeline','Containerize a multi-tier web application with Docker Compose and set up GitHub Actions automated build and test runner.','2026-10-18',53,NULL,NULL),(7,7,'RSA Cryptographic Implementation & Vulnerability Audit','Write a modular arithmetic RSA key generator in Python and submit a penetration testing report on an OWASP vulnerable lab.','2026-10-20',54,NULL,NULL),(8,2,'unit1','finish it in 10 days','2026-10-15',49,'uploads/assignments/asg_1791488155_451cd8.jpeg','pic-13.jpeg');
