INSERT INTO `notices` VALUES (1,'Central Academic Council: Continuous Internal Assessment II Schedule','All 3rd Year engineering students are notified that CIA-2 examinations for Semester 5 will commence from October 12, 2026. Hall tickets and seating plans will be available on the portal.',2,'2026-09-24 14:12:11'),(2,'AI & Cloud Computing Technical Symposium - Call for Papers','Department of Computer Science invites research paper submissions for the upcoming National Technical Summit 2026. Cash awards and publication opportunities for shortlisted student teams.',52,'2026-09-24 14:12:11'),(3,'Mandatory 75% Attendance Compliance Reminder','Students falling below 75% attendance in any core course are advised to meet their respective faculty advisors immediately to review attendance recovery plans before model examinations.',51,'2026-09-24 14:12:11');
